import * as brevo from "@getbrevo/brevo";
import { json } from "@sveltejs/kit";
import { P as PUBLIC_BREVO_API_KEY } from "../../../../chunks/public.js";
async function POST({ request }) {
  try {
    const { email } = await request.json();
    const apiInstance = new brevo.ContactsApi();
    apiInstance.setApiKey(brevo.ContactsApiApiKeys.apiKey, PUBLIC_BREVO_API_KEY);
    const createContact = new brevo.CreateContact();
    createContact.email = email;
    createContact.listIds = [8];
    createContact.updateEnabled = true;
    await apiInstance.createContact(createContact);
    return json({
      success: true,
      message: "Inscrição realizada com sucesso!"
    });
  } catch (error) {
    console.error("Erro ao inscrever na newsletter:", error);
    if (error.response?.text?.includes("Contact already exist")) {
      return json({
        success: false,
        message: "Este email já está inscrito em nossa newsletter."
      }, { status: 400 });
    }
    return json({
      success: false,
      message: "Erro ao realizar inscrição. Por favor, tente novamente."
    }, { status: 500 });
  }
}
export {
  POST
};
